   const state=base();state.cards.push({id:'source',owner:'player',zone:'character',type:'Character',rested:false},{id:'fish-man',owner:'player',zone:'character',type:'Character',cost:5,traits:['Fish-Man']},{id:'wrong-trait',owner:'player',zone:'character',type:'Character',cost:4,traits:['Other']},{id:'over-cost',owner:'player',zone:'character',type:'Character',cost:6,traits:['Fish-Man']});const paid=payEffectCost(state,'player',ability!.costs[0],{targetId:'source',sourceCardId:'source'});assert(!paid.error&&paid.state.cards.find(card=>card.id==='source')?.rested===true,'Activation must rest this Character as its cost');const selected=applyEffectAction(paid.state,'player',granted,{cardIds:['fish-man']});assert(!selected.error&&!selected.requiresSelection&&selected.state.cards.find(card=>card.id==='fish-man')?.temporaryKeywords?.includes('blocker'),'Paid activation did not grant Blocker to the eligible Fish-Man');for(const id of ['wrong-trait','over-cost']){const rejected=applyEffectAction(paid.state,'player',granted,{cardIds:[id]});assert(Boolean(rejected.error)&&!rejected.state.cards.find(card=>card.id===id)?.temporaryKeywords?.includes('blocker'),`Illegal Blocker recipient ${id} was accepted`);}
